import React, { useState } from 'react';
import { escapeHTML } from '../utils/security';

const SearchForm = ({ onSearch, onReset, properties }) => {
  const [formData, setFormData] = useState({
    type: 'any',
    minPrice: '',
    maxPrice: '',
    minBedrooms: '',
    maxBedrooms: '',
    postcode: '',
    startDate: '',
    endDate: ''
  });

  // Extract unique property types and postcodes
  const propertyTypes = ['any', 'House', 'Flat'];
  const postcodes = Array.from(new Set(properties.map(p => p.postcode)));
  
  const priceRange = {
    min: Math.min(...properties.map(p => p.price)),
    max: Math.max(...properties.map(p => p.price))
  };

  const bedroomOptions = [1, 2, 3, 4, 5];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: escapeHTML(value)
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSearch(formData);
  };

  const handleReset = () => {
    setFormData({
      type: 'any',
      minPrice: '',
      maxPrice: '',
      minBedrooms: '',
      maxBedrooms: '',
      postcode: '',
      startDate: '',
      endDate: ''
    });
    onReset();
  };

  const formatPrice = (price) => {
    return `£${price.toLocaleString()}`;
  };

  return (
    <form className="search-form" onSubmit={handleSubmit}>
      <div className="form-section">
        <h3>Property Type</h3>
        <select
          name="type"
          value={formData.type}
          onChange={handleChange}
          className="form-select"
        >
          <option value="any">Any Type</option>
          <option value="House">House</option>
          <option value="Flat">Flat</option>
        </select>
      </div>

      <div className="form-section">
        <h3>Price Range (£)</h3>
        <div className="range-inputs">
          <input
            type="number"
            name="minPrice"
            placeholder="Min price"
            value={formData.minPrice}
            onChange={handleChange}
            className="form-input"
            min={priceRange.min}
            max={priceRange.max}
          />
          <span className="range-separator">to</span>
          <input
            type="number"
            name="maxPrice"
            placeholder="Max price"
            value={formData.maxPrice}
            onChange={handleChange}
            className="form-input"
            min={priceRange.min}
            max={priceRange.max}
          />
        </div>
      </div>

      <div className="form-section">
        <h3>Bedrooms</h3>
        <div className="range-inputs">
          <select
            name="minBedrooms"
            value={formData.minBedrooms}
            onChange={handleChange}
            className="form-select"
          >
            <option value="">Min bedrooms</option>
            {bedroomOptions.map(num => (
              <option key={`min-${num}`} value={num}>{num}</option>
            ))}
          </select>
          <span className="range-separator">to</span>
          <select
            name="maxBedrooms"
            value={formData.maxBedrooms}
            onChange={handleChange}
            className="form-select"
          >
            <option value="">Max bedrooms</option>
            {bedroomOptions.map(num => (
              <option key={`max-${num}`} value={num}>{num}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="form-section">
        <h3>Postcode Area</h3>
        <select
          name="postcode"
          value={formData.postcode}
          onChange={handleChange}
          className="form-select"
        >
          <option value="">Select postcode</option>
          {postcodes.map(pc => (
            <option key={pc} value={pc}>{pc}</option>
          ))}
        </select>
      </div>

      <div className="form-section date-range">
        <h3>Date Added</h3>
        <div className="date-inputs">
          <div className="date-input">
            <label>From:</label>
            <input
              type="date"
              name="startDate"
              value={formData.startDate}
              onChange={handleChange}
              className="form-input"
            />
          </div>
          <div className="date-input">
            <label>To:</label>
            <input
              type="date"
              name="endDate"
              value={formData.endDate}
              onChange={handleChange}
              className="form-input"
            />
          </div>
        </div>
      </div>

      <div className="form-actions">
        <button type="submit" className="btn btn-primary">
          Search Properties
        </button>
        <button type="button" className="btn btn-secondary" onClick={handleReset}>
          Clear All
        </button>
      </div>
    </form>
  );
};

export default SearchForm;
